from pathlib import Path

MARKER='APPLE_SEED_30_FULL_THEMES_V1'
BUILDER=Path('site-builder.html')
RUNTIME=Path('site-builder-runtime.js')
names=['Apple Classic','Swiss Studio','Bento Pro','Glass House','Neo Brutal','Luxury Gold','Editorial','Cyber Lab','Soft Bloom','Compact Pro','Split Focus','Centered','Dark Glass','Cyber Grid','Green Workshop','Warm Studio','Monochrome','Ultra Round','Sharp Edge','Magazine','Repair Dashboard','Aurora','Pure Minimal','Framed','Gradient Flow','High Contrast','Airy','Dense Pro','Retro Print','Future Tech']
script='''<script id="APPLE_SEED_30_FULL_THEMES_V1">\n(function(){\n'use strict';\nconst KEY='APPLE_SEED_FULL_THEME_V1';\nconst THEMES=__THEMES__;\nlet panel,grid,status;\nfunction valid(v){v=String(v||'01');return /^(?:[1-9]|[12][0-9]|30)$/.test(v)?v.padStart(2,'0'):'01'}\nfunction current(){try{return valid(localStorage.getItem(KEY)||draft?.full_theme_id||'01')}catch(_){return valid(draft?.full_theme_id||'01')}}\nfunction apply(v){v=valid(v);const f=document.getElementById('preview'),d=f&&f.contentDocument;if(!d||!d.documentElement)return;const r=d.documentElement;for(let i=1;i<=30;i++)r.classList.remove('as-full-theme-'+String(i).padStart(2,'0'));r.classList.add('as-full-theme-scope','as-full-theme-'+v);let l=d.getElementById('apple-seed-full-themes-link');if(!l){l=d.createElement('link');l.id='apple-seed-full-themes-link';l.rel='stylesheet';l.href='site-builder-full-themes.css?v=20260912-full1';(d.head||r).appendChild(l)}}\nfunction render(v){if(!grid)return;grid.querySelectorAll('[data-full-theme]').forEach(x=>x.classList.toggle('active',x.dataset.fullTheme===v));if(status)status.textContent='Đang chọn: Giao diện '+v+' — '+THEMES[parseInt(v,10)-1]}\nfunction set(v){v=valid(v);draft.full_theme_id=v;try{localStorage.setItem(KEY,v)}catch(_){}apply(v);render(v);if(typeof saveDraft==='function')saveDraft();if(typeof toast==='function')toast('🎭 Đã chọn giao diện '+v)}\nfunction init(){if(panel)return;const right=document.querySelector('.side.right');if(!right)return;panel=document.createElement('div');panel.className='panel';panel.id='appleSeedFullThemePanel';panel.innerHTML='<h3>🎭 30 Giao diện hoàn chỉnh</h3><div class="muted" style="margin-bottom:8px">30 bố cục/style website khác nhau. Không thay thế 30 bảng màu.</div><div id="appleSeedFullThemeGrid" class="as-full-theme-grid"></div><div id="appleSeedFullThemeStatus" style="margin-top:8px;font-size:10px;font-weight:850;color:#1769ff"></div><button class="btn" id="appleSeedFullThemeReset" type="button" style="width:100%;margin-top:7px">↺ Giao diện Apple Classic</button>';right.insertBefore(panel,right.firstElementChild);grid=panel.querySelector('#appleSeedFullThemeGrid');status=panel.querySelector('#appleSeedFullThemeStatus');grid.innerHTML=THEMES.map((n,i)=>'<button type="button" class="as-full-theme-choice" data-full-theme="'+String(i+1).padStart(2,'0')+'"><span class="as-full-preview p'+String(i+1).padStart(2,'0')+'"><i></i><b></b><em></em></span><strong>'+String(i+1).padStart(2,'0')+' · '+n+'</strong></button>').join('');grid.querySelectorAll('[data-full-theme]').forEach(x=>x.onclick=()=>set(x.dataset.fullTheme));panel.querySelector('#appleSeedFullThemeReset').onclick=()=>set('01');render(current());apply(current())}\nconst f=document.getElementById('preview');if(f)f.addEventListener('load',()=>setTimeout(()=>apply(current()),300));\nconst t=setInterval(()=>{if(document.querySelector('.side.right')){init();clearInterval(t)}},100);setTimeout(()=>clearInterval(t),30000);\nsetInterval(()=>{const v=current();apply(v);render(v)},1500);\ndocument.addEventListener('click',function(e){const b=e.target.closest&&e.target.closest('#publish');if(b){try{draft.full_theme_id=current()}catch(_){}}},true);\n})();\n</script>\n'''.replace('__THEMES__',repr(names))
css='''\n/* APPLE_SEED_30_FULL_THEMES_UI */\n.as-full-theme-grid{display:grid;grid-template-columns:1fr 1fr;gap:6px;max-height:520px;overflow:auto}.as-full-theme-choice{border:1px solid #dfe5ed;background:#fff;border-radius:10px;padding:6px;text-align:left;cursor:pointer;min-width:0}.as-full-theme-choice:hover{border-color:#1769ff;transform:translateY(-1px)}.as-full-theme-choice.active{border-color:#1769ff;box-shadow:inset 0 0 0 2px #1769ff;background:#f5f8ff}.as-full-theme-choice strong{display:block;font-size:9px;line-height:1.25;margin-top:5px;color:#344054;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.as-full-preview{height:62px;border-radius:7px;display:block;position:relative;overflow:hidden;background:#f8fafc;border:1px solid #dbe2ea}.as-full-preview:before{content:"";position:absolute;left:0;right:0;top:0;height:9px;background:#e2e8f0}.as-full-preview i,.as-full-preview b,.as-full-preview em{position:absolute;display:block;border-radius:4px}.as-full-preview i{left:7px;right:7px;top:15px;height:19px;background:#dbeafe}.as-full-preview b{left:7px;top:40px;width:26%;height:14px;background:#2563eb}.as-full-preview em{left:35%;right:7px;top:40px;height:14px;background:#e5e7eb}.p02 i{background:#fff;border-bottom:2px solid #111827}.p03 i{border-radius:8px;background:#eef2ff}.p04{background:linear-gradient(135deg,#dbeafe,#f5f3ff)}.p04 i{background:#ffffffaa}.p05{background:#fff}.p05 i,.p05 b,.p05 em{border:2px solid #111827;border-radius:0}.p06{background:#fbf5e7}.p06 i{background:#d4af37}.p07 i{height:24px;background:#e7e5e4}.p08{background:#06131b}.p08:before{background:#083344}.p08 i{background:#0e7490}.p08 b{background:#22d3ee}.p09{background:#fff1f2}.p09 i{background:#fce7f3;border-radius:12px}.p10 i{height:15px;top:18px}.p10 b,.p10 em{height:11px;top:39px}.p11 i{left:7px;right:43%;background:#dbeafe}.p11 b{left:58%;width:35%}.p12 i{left:18%;right:18%;background:#eef2ff}.p12 b{left:37%;width:26%}.p13{background:#111827}.p13:before{background:#0b1220}.p13 i{background:#ffffff18}.p13 b{background:#a78bfa}.p14{background:#030712}.p14 i{background:#062f35;border:1px solid #22d3ee}.p14 b{background:#22d3ee}.p15{background:#ecfdf5}.p15 i{background:#d1fae5}.p15 b{background:#15803d}.p16{background:#fff7ed}.p16 i{background:#fed7aa}.p16 b{background:#b45309}.p17{background:#fff}.p17 i,.p17 b{background:#111}.p18 i{border-radius:18px;background:#e0e7ff}.p19 i{border-radius:2px;background:#e2e8f0}.p20 i{height:28px;background:#f1f5f9}.p21{background:#f8fafc}.p21 i{background:#e2e8f0}.p21 b{background:#475569}.p22{background:linear-gradient(135deg,#eef2ff,#ecfeff)}.p22 i{background:#c7d2fe}.p23 i{background:transparent;border:0}.p23 b{background:#111827}.p24 i{background:#fff;border:2px solid #64748b}.p25{background:linear-gradient(135deg,#ede9fe,#fce7f3)}.p25 i{background:#c4b5fd}.p26{background:#fff}.p26 i{background:#111827}.p26 b{background:#facc15}.p27 i{left:14%;right:14%;background:#f8fafc}.p28 i{height:15px;top:18px}.p28 b,.p28 em{height:10px;top:38px}.p29{background:#fff7ed}.p29 i{background:#fed7aa}.p29 b{background:#7c2d12}.p30{background:#07111f}.p30:before{background:#0f2740}.p30 i{background:linear-gradient(90deg,#1d4ed8,#06b6d4)}.p30 b{background:#60a5fa}.p30 em{background:#172554}\n'''
s=BUILDER.read_text(encoding='utf-8')
if MARKER not in s:
    s=s.replace('</head>','<link rel="stylesheet" href="site-builder-full-themes.css?v=20260912-full1">\n<!-- '+MARKER+' -->\n</head>',1)
    s=s.replace('</style>','<style id="apple-seed-full-theme-ui">'+css+'</style>\n</style>',1)
    pos=s.find("<script id='APPLE_SEED_HERO_MODE_ADMIN_V1'>")
    if pos<0: pos=s.find('<script id="APPLE_SEED_HERO_MODE_ADMIN_V1">')
    if pos<0: raise SystemExit('Hero mode marker missing; refusing to patch Builder')
    s=s[:pos]+script+s[pos:]
    BUILDER.write_text(s,encoding='utf-8')
r=RUNTIME.read_text(encoding='utf-8')
if 'APPLE_SEED_30_FULL_THEMES_RUNTIME_V1' not in r:
    marker='  function applyHeroMode(mode){'
    if marker not in r: raise SystemExit('Hero runtime marker missing; refusing to patch runtime')
    ins='''  function applyFullTheme(themeId){\n    var v=/^(?:[1-9]|[12][0-9]|30)$/.test(String(themeId||''))?String(themeId).padStart(2,'0'):'01';\n    try{\n      var st=document.getElementById('apple-seed-full-themes-runtime');\n      if(!st){st=document.createElement('link');st.id='apple-seed-full-themes-runtime';st.rel='stylesheet';st.href='site-builder-full-themes.css?v=20260912-full1';(document.head||root).appendChild(st)}\n      for(var i=1;i<=30;i++)root.classList.remove('as-full-theme-'+String(i).padStart(2,'0'));\n      root.classList.add('as-full-theme-scope','as-full-theme-'+v);\n    }catch(_){ }\n  }\n\n  /* APPLE_SEED_30_FULL_THEMES_RUNTIME_V1 */\n  function applyHeroMode(mode){'''
    r=r.replace(marker,ins,1)
    hook='      applyTheme(data&&data.config&&data.config.theme_id);'
    if hook not in r: raise SystemExit('Theme runtime hook missing; refusing to patch runtime')
    r=r.replace(hook,hook+'\n      applyFullTheme(data&&data.config&&data.config.full_theme_id);',1)
    RUNTIME.write_text(r,encoding='utf-8')
print('30 full themes installed')
